pid_t pid = fork();

if (pid == -1) {
    // Error: Process creation failed
    // perror("fork");
}

if (pid == 0) {
    // Child Process Context (PID = 0)
    // Inherits parent's memory image (Copy-on-Write)
    printf("Child executing...");
} else {
    // Parent Process Context (PID > 0)
    // 'pid' holds the Child's PID
    printf("Parent waiting...");
    wait(NULL); // Ensures child finishes first
}
